// This file is generated by AI.

// 资源浏览器: 浏览项目 game/ 下的资源 (排除 scene), 左侧目录树 + 右侧预览。
// 缩略图与媒体均通过预览服务器的 overlay 站点 URL 加载。

import { useEffect, useState } from 'react';

import { fs } from '../lib/fs';
import { previewClient } from '../preview/client';
import { useAppStore } from '../state/store';
import { FileTree, type FileNode } from './FileTree';

export function ResourceBrowser() {
  const projectPath = useAppStore((s) => s.projectPath);
  const settings = useAppStore((s) => s.settings);
  const [assetBase, setAssetBase] = useState<string | null>(null);
  const [selected, setSelected] = useState<FileNode | null>(null);
  const [textPreview, setTextPreview] = useState<string | null>(null);

  // 确保预览服务器与 overlay 站点可用, 以构建资源 URL
  useEffect(() => {
    if (!projectPath) return;
    let cancelled = false;
    void previewClient.ensureSite(projectPath, settings.enginePath ?? undefined).then((url) => {
      if (!cancelled) setAssetBase(url);
    });
    return () => {
      cancelled = true;
    };
  }, [projectPath, settings.enginePath]);

  useEffect(() => {
    setSelected(null);
  }, [projectPath]);

  // 文本文件预览 (媒体直接走 URL)
  useEffect(() => {
    setTextPreview(null);
    if (!selected || selected.kind !== 'text') return;
    let cancelled = false;
    void fs
      .readText(selected.path)
      .then((text) => {
        if (!cancelled) setTextPreview(text.slice(0, 20000));
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [selected]);

  const assetUrl = (rel: string): string | undefined => {
    if (!assetBase) return undefined;
    return `${assetBase}game/${rel.split('/').map(encodeURIComponent).join('/')}`;
  };

  if (!projectPath) return <div className="resource-browser empty">未打开项目</div>;

  return (
    <div className="resource-browser">
      <div className="resource-files">
        <FileTree
          rootPath={`${projectPath}\\game`}
          excludeTop={(name) => name === 'scene'}
          selectedPath={selected?.path ?? null}
          assetUrl={assetUrl}
          onOpen={(file) => setSelected(file)}
        />
      </div>
      <div className="resource-preview">
        {selected ? (
          selected.kind === 'image' && assetUrl(selected.rel) ? (
            <img src={assetUrl(selected.rel) ?? undefined} alt={selected.name} />
          ) : selected.kind === 'audio' && assetUrl(selected.rel) ? (
            <audio src={assetUrl(selected.rel) ?? undefined} controls />
          ) : selected.kind === 'video' && assetUrl(selected.rel) ? (
            <video src={assetUrl(selected.rel) ?? undefined} controls />
          ) : selected.kind === 'text' && textPreview !== null ? (
            <pre>{textPreview}</pre>
          ) : (
            <span className="muted">该类型暂无预览</span>
          )
        ) : (
          <span className="muted">选择文件以预览</span>
        )}
      </div>
    </div>
  );
}
